#ifndef TD_PSOLA_AUTOTUNE_H
#define TD_PSOLA_AUTOTUNE_H

#include <stddef.h>
#include <stdint.h>

#define TD_PSOLA_SAMPLE_RATE_HZ 48000U

/** Status values returned by the research TD-PSOLA autotune processor. */
typedef enum
{
    TD_PSOLA_STATUS_OK = 0,
    TD_PSOLA_STATUS_NULL_POINTER,
    TD_PSOLA_STATUS_INVALID_LENGTH,
    TD_PSOLA_STATUS_INVALID_CONFIG,
    TD_PSOLA_STATUS_ALLOCATION_FAILED
} TdPsolaStatus;

/**
 * Configuration for the host-side TD-PSOLA autotune experiment.
 *
 * strength = 1.0 applies the full correction to the nearest chromatic note;
 * lower values apply a softer correction. The other values normally should be
 * left at their defaults for voice.
 */
typedef struct
{
    float strength;
    float confidence_threshold;
    float min_pitch_hz;
    float max_pitch_hz;
} TdPsolaConfig;

/** Summary information useful when comparing audible results. */
typedef struct
{
    size_t analysis_frames;
    size_t voiced_frames;
    float mean_detected_pitch_hz;
    float mean_target_pitch_hz;
    float minimum_applied_ratio;
    float maximum_applied_ratio;
} TdPsolaStats;

/**
 * @brief Fill a configuration structure with the recommended voice settings.
 * @param config Configuration to initialise. NULL is safely ignored.
 */
void TdPsola_DefaultConfig(TdPsolaConfig *config);

/**
 * @brief Process a complete mono 48 kHz, signed 16-bit PCM buffer using a
 *        TD-PSOLA chromatic pitch-correction experiment.
 *
 * This implementation is intentionally an offline/host research processor. It
 * uses overlapping 2048-sample frames and allocates overlap-add work buffers
 * proportional to the recording length. That is useful for audible algorithm
 * comparison before committing to an STM32 streaming implementation.
 *
 * @param input Input samples.
 * @param output Output buffer with room for sample_count samples. It may be the
 *               same buffer as input.
 * @param sample_count Number of mono samples.
 * @param config Optional configuration; NULL selects defaults.
 * @param stats Optional output statistics; may be NULL.
 * @return Processing status.
 */
TdPsolaStatus TdPsola_ProcessBuffer(const int16_t *input,
                                    int16_t *output,
                                    size_t sample_count,
                                    const TdPsolaConfig *config,
                                    TdPsolaStats *stats);

/**
 * @brief Quantise a positive frequency to the nearest equal-tempered semitone.
 * @param input_hz Input pitch in hertz.
 * @return Target pitch in hertz, or 0 for invalid input.
 */
float TdPsola_ChromaticTargetHz(float input_hz);

#endif
